import java.util.HashMap;
import java.util.Map;

public class TypedSettingsReaderTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        Map<String, Object> raw = new HashMap<>();
        raw.put("port", 8080);
        raw.put("host", "localhost");
        raw.put("debug", true);

        TypedSettingsReader settings = new TypedSettingsReader(raw);
        check("getInt on an Integer", 8080, settings.getInt("port", 80));
        check("getText on a String", "localhost", settings.getText("host", "none"));
        check("getFlag on a Boolean", true, settings.getFlag("debug", false));

        check("getInt on a String falls back", 80, settings.getInt("host", 80));
        check("getText on an Integer falls back", "none", settings.getText("port", "none"));
        check("every bad read is reported in order", "[host, port]", settings.problems().toString());

        String missing = settings.getInt("timeout", 5) + " " + settings.problems();
        check("a missing key falls back without being reported", "5 [host, port]", missing);

        TypedSettingsReader empty = new TypedSettingsReader(null);
        check("a null map behaves like an empty one", "fallback", empty.getText("host", "fallback"));

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

