import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * TASK: Complete TypedSettingsReader, which reads typed values out of a
 * Map<String, Object> without ever throwing ClassCastException.
 *
 * Every getter must GUARD the cast with instanceof and report the keys that
 * held the wrong type instead of crashing.
 *
 * Rules for getInt / getText / getFlag:
 *   - the key is missing  -> return the fallback, record NOTHING
 *   - the value has the right type (Integer / String / Boolean) -> return it
 *   - the value has the WRONG type -> return the fallback AND append the key
 *     to problems(), once per bad read (asking twice records it twice)
 *   - a null map behaves like an empty map
 *
 * Example: with {"port": 8080, "host": "localhost"},
 *   getInt("port", 80) is 8080, getInt("host", 80) is 80 and problems()
 *   is then [host].
 */
public class TypedSettingsReader {

    private final Map<String, Object> values;
    private final List<String> problems = new ArrayList<>();

    public TypedSettingsReader(Map<String, Object> values) {
        this.values = values == null ? new HashMap<>() : values;
    }

    public int getInt(String key, int fallback) {
        Object raw = values.get(key);
        if (raw == null) {
            return fallback;
        }
        if (raw instanceof Integer number) {
            return number;
        }
        problems.add(key);
        return fallback;
    }

    public String getText(String key, String fallback) {
        Object raw = values.get(key);
        if (raw == null) {
            return fallback;
        }
        if (raw instanceof String text) {
            return text;
        }
        problems.add(key);
        return fallback;
    }

    public boolean getFlag(String key, boolean fallback) {
        Object raw = values.get(key);
        if (raw == null) {
            return fallback;
        }
        if (raw instanceof Boolean flag) {
            return flag;
        }
        problems.add(key);
        return fallback;
    }

    public List<String> problems() {
        return new ArrayList<>(problems);
    }
}
